void can_v_id_class_create (const Can_Dev_Id can_dev_id , const ID_Class_Extract id_class_extract)
{
  Can_V_Rx curr ;

  for (curr = can_v_vars.init.can_v_rx_list ; curr ; curr = curr->obj.init.next)
    {
      curr->obj.init.id_set = can_v_lut_extract_class (can_dev_id , curr->obj.init.can_lut_sw , id_class_extract) ;
    }
}

